import{_ as l,l as i,o as e,c as s,v as t,p,x as o,d,i as n,S as c}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"类型反馈与推测","description":"","frontmatter":{"title":"类型反馈与推测","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/type-feedback.md","filePath":"cs/type-feedback.md","lastUpdated":1789023840000}'),h={name:"cs/type-feedback.md"};function _(f,a,E,m,u,B){const r=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="类型反馈与推测" tabindex="-1">类型反馈与推测 <a class="header-anchor" href="#类型反馈与推测" aria-label="Permalink to &quot;类型反馈与推测&quot;">​</a></h1><div class="epigraph"><p>解释器或 IC 记录操作数见到的类型（或范围），JIT 按最常见类型特化代码，其它类型走去优化。反馈是轮廓在类型上的投影。</p><footer>—— 据 Hölzle and Ungar；Gal et al. 类型特化；对照[PGO](/cs/pgo) 与[渐进类型](/cs/gradual-typing) 整理</footer></div><p>上一课<a href="/cs/deoptimization">去优化</a> 提供失败通道。缺口是<strong>投机依据</strong>：类型反馈。<code>+</code> 在 JS 见过的都是 int，则发整数加，溢出或对象则 deopt。本课钉剖析数据结构，分层编译下一课用同一反馈升层。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态 HM 在动态语言上没有。运行时：每个字节码或调用点一个 profile（位图、类型链）。JIT 读 profile 生成守卫。缺口是<strong>收集与消费</strong>，不是 deopt 帧格式。</p><p>与渐进：静态注解是程序员；反馈是机器观察。可同时存在。</p><h3 id="反馈不是证明" tabindex="-1">反馈不是证明 <a class="header-anchor" href="#反馈不是证明" aria-label="Permalink to &quot;反馈不是证明&quot;">​</a></h3><p>罕见类型没见到 ≠ 不会出现。必须守卫。不要删 deopt 路径。</p><p><span class="marginnote">Self/HotSpot 类型 profile。V8 FeedbackVector。本课与 PGO 对照：一个在线、一个离线。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>解释器更新计数（要廉价：饱和计数器）。编译：若单类型占 99% 则特化。Megamorphic 放弃。再编译：profile 变了则作废代码。</p>',11)),(e(),p(c,null,{default:o(()=>[n(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20INT%5B%22%E8%A7%A3%E9%87%8A%E5%99%A8%22%5D%20--%3E%20FB%5B%22%E7%B1%BB%E5%9E%8B%20%2F%20%E5%80%BC%E5%8F%8D%E9%A6%88%22%5D%0A%20%20FB%20--%3E%20JIT%5B%22%E7%89%B9%E5%8C%96%E7%BC%96%E8%AF%91%22%5D%0A%20%20JIT%20--%3E%20GRD%5B%22%E5%AE%88%E5%8D%AB%22%5D%0A%20%20GRD%20--%3E%20DEOPT%5B%22%E5%A4%B1%E8%B4%A5%E5%8E%BB%E4%BC%98%E5%8C%96%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与值范围：反馈可含常见立即数，用于推测常量。与 IC：IC 状态本身是反馈。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>多线程：profile 更新竞态可接受近似。不要为精确用全局锁。污染：一个调用点见过太多类型则永远慢——可分裂调用点（克隆方法）。</p><p>与<a href="/cs/sccp">SCCP</a>：静态常量 vs 动态常见值，后者必须检查。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写分层阈值数字。后课默认：动态语言 JIT 吃类型反馈。下一课分层编译：解释器 → C1 → C2。</p><p>也不把反馈当推荐系统。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>类型反馈：在线轮廓驱动特化。</li><li>必须保留去优化；反馈不是类型系统。</li><li>IC 是调用点上的反馈。</li><li>出处：Hölzle and Ungar；Gal et al.；对照 PGO。</li></ul>',9))])}const b=l(h,[["render",_]]);export{A as __pageData,b as default};
